/**
 * Get all photos by a specific photographer
 */
export function getPhotosByPhotographer(photographer: Photo['photographer']): Photo[] {
  return photos2025.filter(photo => photo.photographer === photographer);
}

/**
 * Get all photos with a specific category
 */
export function getPhotosByCategory(category: string): Photo[] {
  return photos2025.filter(photo => photo.categories.includes(category));
}

/**
 * Get all unique categories
 */
export function getAllCategories(): string[] {
  const categories = new Set<string>();
  photos2025.forEach(photo => {
    photo.categories.forEach(cat => categories.add(cat));
  });
  return Array.from(categories).sort();
}

/**
 * Search photos by caption text
 */
export function searchPhotos(query: string): Photo[] {
  const lowerQuery = query.toLowerCase();
  return photos2025.filter(photo =>
    photo.caption.toLowerCase().includes(lowerQuery) ||
    photo.filename.toLowerCase().includes(lowerQuery)
  );
}

/**
 * Get random photo from collection
 */
export function getRandomPhoto(): Photo {
  return photos2025[Math.floor(Math.random() * photos2025.length)];
}

/**
 * Get photos by multiple categories (AND logic)
 */
export function getPhotosByCategories(categories: string[]): Photo[] {
  return photos2025.filter(photo =>
    categories.every(cat => photo.categories.includes(cat))
  );
}
